def get_pokemon_locations(
    is_white2: bool = False,
    randomise_wild: bool = False,
    randomise_statics: bool = False,
    seed: int = 0,
) -> dict[str, list[int]]:
    import random
    base_wild = WHITE2_WILD_LOCATIONS if is_white2 else BLACK2_WILD_LOCATIONS
    base_statics = STATIC_ENCOUNTERS_W2 if is_white2 else STATIC_ENCOUNTERS_B2

    locs: dict[str, list[int]] = {}

    if not randomise_wild:
        for loc_name, species_list in base_wild.items():
            locs[loc_name] = list(species_list)
    else:
        rng = random.Random(seed)
        for loc_name, species_list in base_wild.items():
            new_species = set()
            for _ in species_list:
                new_species.add(rng.randint(1, 649))
            locs[loc_name] = sorted(new_species)

    if not randomise_statics:
        for s_name, s_pokes in base_statics.items():
            locs[s_name] = list(s_pokes)
    else:
        rng = random.Random(seed ^ 0x57A71C)
        for s_name in base_statics:
            locs[s_name] = [rng.randint(1, 649)]

    return locs
